// Bit-exact parity test for the EXTENDED decoder step (decoder_full).
//
// Compares C++ run_decoder_step_full against vectors generated by the REAL
// Qwen4-Exp module stack (tools/gen_decoder_full_vectors.py): a mixed stack of
// 2 GDN linear layers + 1 QSA full-attention layer, with NON-ZERO shared
// experts. All comparisons reinterpret floats as raw uint32 bits.
//
//   cd /Users/vincent/Documents/Veystrix && MLXROOT=.venv/lib/python3.12/site-packages/mlx && \
//   xcrun clang++ -std=c++20 -O2 -I"$MLXROOT/include" -Icpp/engine/src \
//     cpp/engine/src/engine.cpp cpp/engine/src/gdn_kernel.cpp cpp/engine/src/gdn_conv.cpp \
//     cpp/engine/src/gdn_layer.cpp cpp/engine/src/qsa.cpp cpp/engine/src/qsa_full.cpp \
//     cpp/engine/src/decoder.cpp cpp/engine/src/decoder_full.cpp \
//     cpp/engine/tests/test_decoder_full.cpp \
//     -L"$MLXROOT/lib" -lmlx -Wl,-rpath,"$(pwd)/$MLXROOT/lib" -o /tmp/test_decoder_full && \
//   /tmp/test_decoder_full cpp/engine/tests/vectors_decoder_full
#include "../src/decoder_full.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) return false;
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static void dump_first_diff(const char* label, const mx::array& a,
                            const mx::array& b) {
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i) {
    if (pa[i] != pb[i]) {
      std::fprintf(stderr, "  %s first diff at %zu: got 0x%08x expected 0x%08x\n",
                   label, i, pa[i], pb[i]);
      return;
    }
  }
}

static std::string meta_text(const std::string& dir) {
  std::ifstream f(dir + "/meta.json");
  std::stringstream ss;
  ss << f.rdbuf();
  return ss.str();
}
static int meta_int(const std::string& txt, const std::string& key) {
  auto p = txt.find("\"" + key + "\": ");
  if (p == std::string::npos) return -1;
  p += key.size() + 4;
  return std::stoi(txt.substr(p));
}
static float meta_float(const std::string& txt, const std::string& key) {
  auto p = txt.find("\"" + key + "\": ");
  if (p == std::string::npos) return -1.0f;
  p += key.size() + 4;
  return std::stof(txt.substr(p));
}
static std::vector<int> meta_int_array(const std::string& txt,
                                       const std::string& key) {
  std::vector<int> out;
  auto p = txt.find("\"" + key + "\": [");
  if (p == std::string::npos) return out;
  p += key.size() + 5;
  while (p < txt.size() && txt[p] != ']') {
    if (txt[p] >= '0' && txt[p] <= '9') {
      out.push_back(std::stoi(txt.substr(p)));
      while (p < txt.size() && txt[p] != ',' && txt[p] != ']') ++p;
    }
    ++p;
  }
  return out;
}
static bool layer_is_full(const std::string& txt, int idx) {
  auto p = txt.find("\"layer_kinds\": [");
  if (p == std::string::npos) return false;
  p += 16;
  for (int i = 0; i < idx; ++i) {
    auto c = txt.find(',', p);
    if (c == std::string::npos) return false;
    p = c + 1;
  }
  while (p < txt.size() && (txt[p] == ' ' || txt[p] == '\n' ||
                            txt[p] == '\r' || txt[p] == '\t' ||
                            txt[p] == '\"')) ++p;
  return txt.compare(p, 4, "full") == 0;
}

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <vectordir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  auto load = [&](const std::string& n) { return mx::load(dir + "/" + n + ".npy"); };
  const std::string meta = meta_text(dir);

  const int n_layers = meta_int(meta, "n_layers");
  const int top_k = meta_int(meta, "top_k");
  const int group_size = meta_int(meta, "group_size");
  const int bits = meta_int(meta, "bits");
  const float eps = meta_float(meta, "eps");

  mx::array embeddings = load("embeddings");
  mx::array position_ids = load("position_ids");
  mx::array lm_head_w = load("lm_head_w");
  mx::array exp_logits = load("expected_logits");

  const int H = static_cast<int>(embeddings.shape(2));
  const int hc_hidden = static_cast<int>(load("L0_attn_norm_w").shape(0));
  const int hc = hc_hidden / H;
  const int vocab = static_cast<int>(exp_logits.shape(2));

  DecoderConfig cfg;
  cfg.hidden_size = H;
  cfg.hc_count = hc;
  cfg.hc_lowrank = static_cast<int>(load("L0_attn_down_w").shape(0));
  cfg.n_layers = n_layers;
  cfg.vocab = vocab;
  cfg.eps = eps;

  FullAttentionConfig fa_cfg;
  fa_cfg.n_heads = meta_int(meta, "n_attn_heads");
  fa_cfg.kv_heads = meta_int(meta, "kv_heads");
  fa_cfg.head_dim = meta_int(meta, "head_dim");
  fa_cfg.n_idx_heads = meta_int(meta, "n_idx_heads");
  fa_cfg.n_idx_kv = meta_int(meta, "n_idx_kv");
  fa_cfg.idx_head_dim = meta_int(meta, "idx_head_dim");
  fa_cfg.compress_ratio = meta_int(meta, "compress_ratio");
  fa_cfg.token_budget = meta_int(meta, "token_budget");
  fa_cfg.eps = eps;
  fa_cfg.rope.dim = meta_int(meta, "rope_dim");
  fa_cfg.rope.base = meta_float(meta, "rope_base");
  fa_cfg.rope.mrope_section = meta_int_array(meta, "mrope_section");
  fa_cfg.rope.style = "interleaved";
  fa_cfg.rope.attention_scaling = 1.0f;

  std::vector<DecoderFullLayer> layers;
  std::vector<DecoderFullLayerCache> caches;
  layers.reserve(n_layers);
  caches.reserve(n_layers);

  for (int l = 0; l < n_layers; ++l) {
    const std::string P = "L" + std::to_string(l) + "_";
    const bool is_full = layer_is_full(meta, l);

    // ---- base weights (hc + routed MoE + shared expert) -------------------
    Q4Projection eg(load(P + "expert_gw"), load(P + "expert_gs"),
                    load(P + "expert_gb"));
    Q4Projection eu(load(P + "expert_uw"), load(P + "expert_us"),
                    load(P + "expert_ub"));
    Q4Projection ed(load(P + "expert_dw"), load(P + "expert_ds"),
                    load(P + "expert_db"));
    SharedExpertWeights shared(load(P + "expert_segw"),
                               load(P + "expert_seuw"),
                               load(P + "expert_sedw"),
                               load(P + "expert_seglw"));

    AttnKind kind = is_full ? AttnKind::FullAttention : AttnKind::Linear;
    std::optional<FullAttentionWeights> full;

    // GDN state is unused for full layers; use L0's (dummy) tensors there.
    const std::string CACHE_P = is_full ? std::string("L0_") : P;
    DecoderLayerCache base_cache(GDNCacheState(
        load(CACHE_P + "conv_state"), load(CACHE_P + "rec_state")));

    if (is_full) {
      full = FullAttentionWeights(
          load(P + "attn_q"), load(P + "attn_k"), load(P + "attn_v"),
          load(P + "attn_o"), load(P + "attn_qn"), load(P + "attn_kn"),
          load(P + "index_qk_w"), load(P + "index_q_norm_w"),
          load(P + "index_k_norm_w"));
      FullAttentionCache fc;
      fc.keys = load(P + "cache_keys");
      fc.values = load(P + "cache_values");
      fc.indexer.index_keys = load(P + "index_keys");
      fc.indexer.index_position_ids = load(P + "index_pos");
      fc.offset = meta_int(meta, "past_len");
      fc.indexer.offset = fc.offset;
      caches.emplace_back(std::move(base_cache), std::move(fc));
    } else {
      // GDN geometry from saved shapes (tracks the generator).
      mx::array w_qkv = load(P + "gdn_qkv"), w_z = load(P + "gdn_z");
      mx::array w_b = load(P + "gdn_b"), w_a = load(P + "gdn_a");
      mx::array conv_w = load(P + "gdn_conv"), A_log = load(P + "gdn_A_log");
      mx::array dt_bias = load(P + "gdn_dt_bias"), norm_w = load(P + "gdn_norm");
      mx::array w_out = load(P + "gdn_out");
      mx::array conv_state = load(P + "conv_state"), rec_state = load(P + "rec_state");
      const int conv_dim = static_cast<int>(w_qkv.shape(0));
      const int value_dim = static_cast<int>(w_z.shape(0));
      const int key_dim = (conv_dim - value_dim) / 2;
      const int Hv = static_cast<int>(A_log.shape(0));
      const int Dk = static_cast<int>(rec_state.shape(3));
      const int Dv = static_cast<int>(rec_state.shape(2));
      const int Hk = key_dim / Dk;
      const int K = static_cast<int>(conv_state.shape(1)) + 1;
      cfg.gdn = GDNConfig{H, key_dim, value_dim, Hk, Hv, Dk, Dv, K, eps,
                          GDNActivation::Sigmoid};

      GDNWeights gw(w_qkv, w_z, w_b, w_a, conv_w, A_log, dt_bias, norm_w, w_out);
      (void)gw;  // gated via base weights below
      DecoderLayerWeights base(
          load(P + "attn_norm_w"), load(P + "attn_down_w"),
          load(P + "attn_up_w"), load(P + "attn_inject_w"),
          GDNWeights(load(P + "gdn_qkv"), load(P + "gdn_z"),
                     load(P + "gdn_b"), load(P + "gdn_a"),
                     load(P + "gdn_conv"), load(P + "gdn_A_log"),
                     load(P + "gdn_dt_bias"), load(P + "gdn_norm"),
                     load(P + "gdn_out")),
          load(P + "mlp_norm_w"), load(P + "mlp_down_w"),
          load(P + "mlp_up_w"), load(P + "mlp_inject_w"),
          load(P + "gate_w"),
          std::move(eg), std::move(eu), std::move(ed),
          top_k, 0.0f, group_size, bits);
      layers.emplace_back(std::move(base), std::move(shared), kind);
      caches.emplace_back(std::move(base_cache));
      continue;
    }

    // Full layer: build base weights (GDN weights are unused but required).
    const std::string P0 = "L0_";
    mx::array w_qkv = load(P0 + "gdn_qkv"), w_z = load(P0 + "gdn_z");
    mx::array w_b = load(P0 + "gdn_b"), w_a = load(P0 + "gdn_a");
    mx::array conv_w = load(P0 + "gdn_conv"), A_log = load(P0 + "gdn_A_log");
    mx::array dt_bias = load(P0 + "gdn_dt_bias"), norm_w = load(P0 + "gdn_norm");
    mx::array w_out = load(P0 + "gdn_out");
    DecoderLayerWeights base(
        load(P + "attn_norm_w"), load(P + "attn_down_w"),
        load(P + "attn_up_w"), load(P + "attn_inject_w"),
        GDNWeights(w_qkv, w_z, w_b, w_a, conv_w, A_log, dt_bias, norm_w, w_out),
        load(P + "mlp_norm_w"), load(P + "mlp_down_w"),
        load(P + "mlp_up_w"), load(P + "mlp_inject_w"),
        load(P + "gate_w"),
        std::move(eg), std::move(eu), std::move(ed),
        top_k, 0.0f, group_size, bits);
    layers.emplace_back(std::move(base), std::move(shared), kind, full);
  }

  DecoderHeadWeights head(load("mix_norm_w"), load("mix_down_w"),
                          load("mix_up_w"), lm_head_w);

  DecoderFullDebug debug;
  mx::array logits = run_decoder_step_full(
      embeddings, layers, head, cfg, fa_cfg, position_ids, caches, &debug);
  mx::eval(logits);

  bool ok = true;
  if (!bit_equal(logits, exp_logits)) {
    std::fprintf(stderr, "FAIL: final logits differ\n");
    dump_first_diff("logits", logits, exp_logits);
    ok = false;
  }

  int full_seen = 0;
  for (int l = 0; l < n_layers; ++l) {
    const std::string P = "L" + std::to_string(l) + "_";
    if (l < static_cast<int>(debug.attn_out.size())) {
      if (!bit_equal(debug.attn_out[l], load(P + "exp_branch"))) {
        std::fprintf(stderr, "FAIL: layer %d attn branch differs\n", l);
        dump_first_diff("branch", debug.attn_out[l], load(P + "exp_branch"));
        ok = false;
      }
    }
    if (l < static_cast<int>(debug.moe_out.size())) {
      if (!bit_equal(debug.moe_out[l], load(P + "exp_moe"))) {
        std::fprintf(stderr, "FAIL: layer %d MoE+shared differs\n", l);
        dump_first_diff("moe", debug.moe_out[l], load(P + "exp_moe"));
        ok = false;
      }
    }
    if (l < static_cast<int>(debug.hidden.size())) {
      if (!bit_equal(debug.hidden[l], load(P + "exp_hidden"))) {
        std::fprintf(stderr, "FAIL: layer %d hidden differs\n", l);
        dump_first_diff("hidden", debug.hidden[l], load(P + "exp_hidden"));
        ok = false;
      }
    }
    if (layer_is_full(meta, l)) {
      if (full_seen < static_cast<int>(debug.qsa_mask.size())) {
        if (!bit_equal(debug.qsa_mask[full_seen], load(P + "exp_mask"))) {
          std::fprintf(stderr, "FAIL: layer %d QSA mask differs\n", l);
          dump_first_diff("qsa_mask", debug.qsa_mask[full_seen],
                          load(P + "exp_mask"));
          ok = false;
        }
        ++full_seen;
      }
    }
  }

  if (!ok) return 1;
  std::printf("test_decoder_full OK (bit-exact, %d layers, %d full-attn)\n",
              n_layers, full_seen);
  return 0;
}
